import { Link, Stack } from 'expo-router';
import { useState } from 'react';
import { FlatList, Pressable, Text, View } from 'react-native';

import licenses from '@/constants/openSourceLicenses.json';
import { useDividerColor } from '@/hooks/useTheme';
import { TOUCH_SLOP } from '@/utils/platform';

type Pkg = { name: string; version: string; license: string; url: string | null; text: number };
const PACKAGES = licenses.packages as Pkg[];
const TEXTS = licenses.texts as string[];

/** Open-source licenses of every package bundled in the app (generated by `npm run licenses`). */
export default function LicensesScreen() {
  const [open, setOpen] = useState<string | null>(null);
  const divider = useDividerColor();
  return (
    <FlatList
      className="flex-1 bg-retrogamingpc-dark"
      contentContainerClassName="w-full self-center p-3 md:max-w-[760px]"
      data={PACKAGES}
      keyExtractor={(p) => `${p.name}@${p.version}`}
      initialNumToRender={30}
      ListHeaderComponent={
        <View className="gap-1 pb-2">
          <Stack.Screen options={{ title: 'Open-source licenses' }} />
          <Text className="text-retrogamingpc-sm text-retrogamingpc-text">
            GamerCred is built with these open-source packages. Thanks to everyone who makes them. Tap a package for its license.
          </Text>
          <Text className="text-retrogamingpc-xs text-retrogamingpc-text-muted">{PACKAGES.length} packages</Text>
        </View>
      }
      renderItem={({ item }) => {
        const key = `${item.name}@${item.version}`;
        const expanded = open === key;
        return (
          <View className="border-b py-1.5" style={{ borderBottomColor: divider }}>
            <Pressable
              accessibilityRole="button"
              accessibilityState={{ expanded }}
              accessibilityLabel={`${item.name}, ${item.license} license`}
              hitSlop={TOUCH_SLOP}
              onPress={() => setOpen(expanded ? null : key)}
              className="min-h-[28px] flex-row items-center justify-between gap-2"
            >
              <Text className="flex-1 text-retrogamingpc-sm text-retrogamingpc-text-bright" numberOfLines={1}>
                {item.name} <Text className="font-mono text-retrogamingpc-xs text-retrogamingpc-text-muted">{item.version}</Text>
              </Text>
              <Text className="text-retrogamingpc-xs text-retrogamingpc-text-muted">
                {item.license} {expanded ? '▾' : '▸'}
              </Text>
            </Pressable>
            {expanded ? (
              <View className="gap-1 pt-1">
                {item.url ? (
                  <Link href={item.url as `https://${string}`} target="_blank" className="text-retrogamingpc-xs text-retrogamingpc-text-bright underline">
                    Source
                  </Link>
                ) : null}
                <View className="retrogamingpc-bevel-inset bg-retrogamingpc-dark p-2">
                  <Text className="font-mono text-retrogamingpc-xs text-retrogamingpc-text" selectable>
                    {TEXTS[item.text]}
                  </Text>
                </View>
              </View>
            ) : null}
          </View>
        );
      }}
    />
  );
}
